"""Quick diagram generator for Shopzy design presentation."""
import os, matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, Circle
plt.rcParams['font.sans-serif'] = 'Arial'
plt.rcParams['font.family'] = 'sans-serif'
D = 'doc/diagrams'
os.makedirs(D, exist_ok=True)

# 1. ARCHITECTURE
fig,ax=plt.subplots(figsize=(14,9),dpi=300); ax.set_xlim(0,14); ax.set_ylim(0,9); ax.axis('off'); fig.patch.set_facecolor('#F8FAFC')
ax.text(7,8.5,"SHOPZY - SYSTEM ARCHITECTURE",ha='center',va='center',fontsize=18,fontweight='bold',color='#0F172A')
ax.text(7,8.15,"React SPA → CDN / WAF → Express API → MongoDB (2dsphere) + Redis Cache",ha='center',va='center',fontsize=11,color='#64748B')
def card(x,y,w,h,t,s,bg='#FFF',bc='#CBD5E1',tc='#0F172A'):
    ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle="round,pad=0.1,rounding_size=0.15",facecolor=bg,edgecolor=bc,linewidth=1.5,zorder=2))
    if t: ax.text(x+w/2,y+h-0.35,t,ha='center',va='center',fontsize=12,fontweight='bold',color=tc,zorder=3)
    if s: ax.text(x+w/2,y+h/2-0.15,s,ha='center',va='center',fontsize=9.5,color='#475569',zorder=3,multialignment='center')
card(0.8,5.8,3.2,1.8,"CLIENT TIER","React 18 SPA (Vite + TS)\nTailwind CSS v4\nZustand + TanStack Query\nRoute-level Code Splitting",bg='#EFF6FF',bc='#3B82F6',tc='#1D4ED8')
card(5.2,5.8,3.6,1.8,"EDGE & NETWORK","Cloudflare / CloudFront CDN\nWAF & DDoS Protection\nSSL / TLS (HSTS)\nNginx Static Asset Cache",bg='#F0FDF4',bc='#22C55E',tc='#15803D')
card(9.8,5.8,3.4,1.8,"API GATEWAY","Node.js 22 + Express + TS\nHelmet, CORS, MongoSanitize\nZod Validators\nJWT Rotation & Blacklist",bg='#FAF5FF',bc='#A855F7',tc='#7E22CE')
ax.annotate('',xy=(5.1,6.7),xytext=(4.1,6.7),arrowprops=dict(arrowstyle="->",color='#2563EB',lw=2,mutation_scale=15))
ax.text(4.6,6.95,"HTTPS",ha='center',va='bottom',fontsize=9,fontweight='bold',color='#2563EB')
ax.annotate('',xy=(9.7,6.7),xytext=(8.9,6.7),arrowprops=dict(arrowstyle="->",color='#16A34A',lw=2,mutation_scale=15))
ax.text(9.3,6.95,"Proxy",ha='center',va='bottom',fontsize=9,fontweight='bold',color='#16A34A')
card(0.8,3.2,12.4,1.9,"EXPRESS REQUEST PIPELINE & SERVICES","Helmet -> CORS -> BodyParsers -> HPP -> MongoSanitize -> RequestContext -> RateLimiter -> Router\n---\nAuthService (JWT/OTP) | ShopService (CRUD) | SearchService ($geoNear) | ReviewService | AdminService\nRule: Services never import Express types",bg='#FFF',bc='#94A3B8',tc='#0F172A')
ax.annotate('',xy=(7.0,5.2),xytext=(11.5,5.7),arrowprops=dict(arrowstyle="->",color='#7C3AED',lw=2,mutation_scale=15,connectionstyle="arc3,rad=0.15"))
card(1.5,0.6,5.0,2.0,"MONGODB","Replica Set\nCollections: Users, Shops, Reviews, Categories, Analytics\n2dsphere, Compound, Text, TTL Indexes\nDenormalized: ratings, priceRange",bg='#ECFDF5',bc='#10B981',tc='#065F46')
card(7.5,0.6,5.0,2.0,"REDIS CACHE","In-Memory Key-Value Store\nTTL Cache: shop:{slug}, shops:search:{hash}\nToken Blacklist: refresh:blacklist:{jti}\nRate Limiter Counters",bg='#FEF2F2',bc='#EF4444',tc='#991B1B')
ax.annotate('',xy=(4.0,2.7),xytext=(4.0,3.1),arrowprops=dict(arrowstyle="<->",color='#059669',lw=2,mutation_scale=15))
ax.annotate('',xy=(10.0,2.7),xytext=(10.0,3.1),arrowprops=dict(arrowstyle="<->",color='#DC2626',lw=2,mutation_scale=15))
plt.tight_layout(); plt.savefig(f'{D}/architecture_diagram.png',dpi=300,facecolor=fig.get_facecolor(),edgecolor='none'); plt.close(); print("1/4 architecture")

# 2. ER DIAGRAM
fig,ax=plt.subplots(figsize=(15,10),dpi=300); ax.set_xlim(0,15); ax.set_ylim(0,10); ax.axis('off'); fig.patch.set_facecolor('#F8FAFC')
ax.text(7.5,9.6,"SHOPZY - ENTITY RELATIONSHIP (ER) DIAGRAM",ha='center',va='center',fontsize=18,fontweight='bold',color='#0F172A')
ax.text(7.5,9.25,"Document Models with GeoJSON 2dsphere, Compound Keys & Denormalization",ha='center',va='center',fontsize=11,color='#64748B')
def ent(x,y,w,h,nm,flds,bc='#2563EB',hb='#DBEAFE'):
    ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle="round,pad=0.05,rounding_size=0.1",facecolor='#FFF',edgecolor=bc,linewidth=1.5,zorder=2))
    ax.add_patch(FancyBboxPatch((x,y+h-0.6),w,0.6,boxstyle="round,pad=0.05,rounding_size=0.1",facecolor=hb,edgecolor=bc,linewidth=1.5,zorder=3))
    ax.text(x+w/2,y+h-0.3,nm,ha='center',va='center',fontsize=11,fontweight='bold',color='#0F172A',zorder=4)
    ty=y+h-0.85
    for f in flds: ax.text(x+0.15,ty,f,ha='left',va='center',fontsize=8.5,color='#334155',fontfamily='monospace',zorder=4); ty-=0.28
ent(0.8,4.8,4.0,3.8,"USER",["+ _id: ObjectId (PK)","- email: String (Unique)","- phone: String (Unique)","- passwordHash (select:false)","- role: customer|owner|admin","- location: GeoJSON (2dsphere)","- preferences: Object","- savedShops: [ObjectId -> Shop]","- searchHistory: [String]"],bc='#2563EB',hb='#BFDBFE')
ent(5.5,4.0,4.2,4.6,"SHOP",["+ _id: ObjectId (PK)","# ownerId: FK -> User","- slug: String (Unique)","- basicInfo: {name, category, tags}","- contact: {phone, email, whatsapp}","- location: GeoJSON (2dsphere)","- businessHours: {schedule, breaks}","- pricing: [{name, price, variants}]","- offers: [{type, value, dates}]","* ratings: {avg, total} DENORM","* priceRange: {min, max} DENORM","- verification: {status, docs}"],bc='#059669',hb='#A7F3D0')
ent(10.4,4.8,3.8,3.6,"REVIEW",["+ _id: ObjectId (PK)","# shopId: FK -> Shop","# userId: FK -> User","- rating: Number (1-5)","- comment: String","- helpful: {count, users[]}","- reply: {comment, repliedAt}","- status: published|hidden","! UNIQUE (shopId, userId)"],bc='#D97706',hb='#FDE68A')
ent(0.8,0.6,4.0,3.0,"CATEGORY",["+ _id: ObjectId (PK)","- name, slug (Unique)","- icon: String","- subCategories: [String]","- displayOrder: Number","- stats: {shopCount}"],bc='#7C3AED',hb='#DDD6FE')
ent(5.5,0.6,4.2,2.9,"ANALYTICS_EVENT",["+ _id: ObjectId (PK)","- eventType: view|click|search","# shopId, userId (FKs)","- metadata: {query, filters}","- location: GeoJSON","! createdAt: TTL 180 Days"],bc='#DC2626',hb='#FECACA')
ent(10.4,0.6,3.8,2.9,"AUDIT_LOG",["+ _id: ObjectId (PK)","- action: String","# actorId: FK -> User","- actorRole, targetEntity","- targetId: ObjectId","- details, ip: String"],bc='#475569',hb='#E2E8F0')
ax.annotate('',xy=(5.4,6.7),xytext=(4.9,6.7),arrowprops=dict(arrowstyle="->",color='#2563EB',lw=2,mutation_scale=15))
ax.text(5.15,6.9,"1 : N (Owns)",ha='center',va='bottom',fontsize=8.5,fontweight='bold',color='#1D4ED8')
ax.annotate('',xy=(10.3,6.5),xytext=(9.8,6.5),arrowprops=dict(arrowstyle="->",color='#059669',lw=2,mutation_scale=15))
ax.text(10.05,6.7,"1 : N",ha='center',va='bottom',fontsize=8.5,fontweight='bold',color='#047857')
ax.annotate('',xy=(12.0,8.5),xytext=(2.8,8.7),arrowprops=dict(arrowstyle="->",color='#D97706',lw=1.8,mutation_scale=15,connectionstyle="arc3,rad=0.25"))
ax.text(7.5,9.0,"User writes Review (1 per user per shop — Unique)",ha='center',va='bottom',fontsize=8.5,fontweight='bold',color='#B45309')
ax.annotate('',xy=(6.5,3.9),xytext=(2.8,3.7),arrowprops=dict(arrowstyle="->",color='#7C3AED',lw=1.8,mutation_scale=15,connectionstyle="arc3,rad=-0.15"))
ax.text(4.2,3.3,"1 : N Categorizes",ha='center',va='center',fontsize=8.5,fontweight='bold',color='#6D28D9')
ax.text(0.8,9.0,"Key: [PK] Primary Key | [FK] Foreign Key | (*) Denormalized | (!) Constraint / TTL",ha='left',va='center',fontsize=9,fontstyle='italic',color='#475569')
plt.tight_layout(); plt.savefig(f'{D}/er_diagram.png',dpi=300,facecolor=fig.get_facecolor(),edgecolor='none'); plt.close(); print("2/4 er_diagram")

