# 4. DFD LEVEL 1
fig,ax=plt.subplots(figsize=(15,10),dpi=300); ax.set_xlim(0,15); ax.set_ylim(0,10); ax.axis('off'); fig.patch.set_facecolor('#F8FAFC')
ax.text(7.5,9.6,"SHOPZY - DFD LEVEL 1 (PROCESS DETAILS)",ha='center',va='center',fontsize=17,fontweight='bold',color='#0F172A')
ax.text(7.5,9.25,"5 internal processes and 4 data stores",ha='center',va='center',fontsize=11,color='#64748B')
def pr(x,y,w,h,pid,nm,col='#2563EB',bgc='#EFF6FF'):
    ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle="round,pad=0.1,rounding_size=0.2",facecolor=bgc,edgecolor=col,linewidth=1.8,zorder=2))
    ax.text(x+w/2,y+h-0.35,pid,ha='center',va='center',fontsize=11,fontweight='bold',color=col,zorder=3)
    ax.text(x+w/2,y+h/2-0.15,nm,ha='center',va='center',fontsize=9.5,fontweight='bold',color='#0F172A',zorder=3,multialignment='center')
def st(x,y,w,h,did,nm):
    ax.plot([x,x+w],[y+h,y+h],color='#0F172A',lw=2,zorder=3); ax.plot([x,x+w],[y,y],color='#0F172A',lw=2,zorder=3)
    ax.fill_between([x,x+w],y,y+h,color='#F1F5F9',zorder=2)
    ax.text(x+0.35,y+h/2,f"[{did}]",ha='left',va='center',fontsize=9,fontweight='bold',color='#0369A1',zorder=4)
    ax.text(x+w/2+0.2,y+h/2,nm,ha='center',va='center',fontsize=9.5,fontweight='bold',color='#0F172A',zorder=4)
pr(1.0,6.5,3.2,1.8,"1.0","AUTHENTICATION\n& IDENTITY",col='#2563EB')
