pr(8.8,1.2,3.6,1.8,"5.0","ADMIN & ANALYTICS\nENGINE",col='#7C3AED',bgc='#FAF5FF')
st(0.8,4.2,3.2,0.9,"D1","User Accounts"); st(5.0,4.2,3.2,0.9,"D2","Shops (2dsphere)"); st(9.2,4.2,2.8,0.9,"D3","Reviews"); st(12.2,4.2,2.4,0.9,"D4","Redis Cache")
